import { z } from 'zod'
import rawMigrations from '../../../resources/data/migrations.json'

/**
 * Texture path migrations between Minecraft versions (resources/data/migrations.json, generated by
 * scripts/gen-migrations.mjs; see docs/versions.md). Imported by main only (not re-exported from
 * '@shared/versions', so the renderer bundle does not carry the table).
 */

const TransitionSchema = z.object({
  from: z.string(),
  to: z.string(),
  renamed: z.array(z.object({ older: z.string(), newer: z.string() })),
  /** Only in `to`: skipped when going down to `from`. */
  added: z.array(z.string()),
  /** Only in `from`: skipped when going up to `to`. */
  removed: z.array(z.string())
})

export const MigrationTableSchema = z.object({
  schemaVersion: z.literal(1),
  description: z.string(),
  generatedAt: z.string(),
  /** Versions of the chain, oldest first. */
  versions: z.array(z.string()).min(1),
  manual: z.array(
    z.object({ from: z.string(), to: z.string(), older: z.string(), newer: z.string() })
  ),
  transitions: z.array(TransitionSchema)
})
export type MigrationTable = z.infer<typeof MigrationTableSchema>

export const migrationTable: MigrationTable = MigrationTableSchema.parse(rawMigrations)

/** Where a path ends up in the other version. */
export type PathMigration =
  | { path: string; renamed: boolean }
  /** The texture does not exist in `version` (a step of the chain added or removed it). */
  | { missingIn: string }

interface Step {
  /** Version reached after this step. */
  version: string
  rename: Map<string, string>
  missing: Set<string>
}

/**
 * Migrates texture paths from one version of the chain to another (down: newer -> older, up: older -> newer).
 * Paths outside assets/minecraft/textures/ are returned unchanged. Throws for versions outside the chain.
 */
export class PathMigrator {
  private readonly steps: Step[]

  constructor(
    readonly from: string,
    readonly to: string,
    table: MigrationTable = migrationTable
  ) {
    const a = table.versions.indexOf(from)
    const b = table.versions.indexOf(to)
    if (a < 0 || b < 0) throw new Error(`No migration chain between ${from} and ${to}`)
    const down = b < a
    const transitions = down
      ? table.transitions.slice(b, a).reverse()
      : table.transitions.slice(a, b)
    this.steps = transitions.map((t) => ({
      version: down ? t.from : t.to,
      rename: new Map(t.renamed.map((r) => (down ? [r.newer, r.older] : [r.older, r.newer]))),
      missing: new Set(down ? t.added : t.removed)
    }))
  }

  /** True when both versions have the same texture paths (nothing to migrate). */
  get identity(): boolean {
    return this.steps.every((s) => s.rename.size === 0 && s.missing.size === 0)
  }

  migrate(path: string): PathMigration {
    let current = path
    let renamed = false
    for (const step of this.steps) {
      if (step.missing.has(current)) return { missingIn: step.version }
      const next = step.rename.get(current)
      if (next) {
        current = next
        renamed = true
      }
    }
    return { path: current, renamed }
  }

  /**
   * Migrates a pack file: a texture PNG, or the `.png.mcmeta` next to one (follows its texture). Other files are
   * returned unchanged.
   */
  migrateFile(path: string): PathMigration {
    if (path.endsWith('.png.mcmeta')) {
      const r = this.migrate(path.slice(0, -'.mcmeta'.length))
      return 'path' in r ? { path: `${r.path}.mcmeta`, renamed: r.renamed } : r
    }
    if (path.startsWith('assets/minecraft/textures/') && path.endsWith('.png'))
      return this.migrate(path)
    return { path, renamed: false }
  }
}

/** Whether a migration chain exists between two versions (both in the table). */
export function canMigrate(
  from: string,
  to: string,
  table: MigrationTable = migrationTable
): boolean {
  return table.versions.includes(from) && table.versions.includes(to)
}
